using VisualRelay.Core.Execution;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

/// <summary>
/// Decision-seam and tier-window resolution tests for <see cref="ActivityWatchdog"/>.
/// Every test drives the watchdog's pure decision functions (DecideOutcome,
/// TryDecideSocketWedge, ResolveTierWindows) with synthetic timestamps and pulse
/// sources — no child processes, no real waiting, no wall-clock sensitivity.
/// These tests do NOT need serialization and run in parallel with all other
/// non-Watchdog tests.
/// </summary>
public sealed class ActivityWatchdogDecisionTests
{
    // Thin wrapper over the pure production decision (ActivityWatchdog.DecideOutcome)
    // so each test sets only the fields its scenario exercises. The inert defaults
    // (huge windows, no ceiling, no wedge sample) mean the decision is Disarmed
    // unless a real threshold is crossed — every fire is therefore explicit.
    private static ActivityWatchdog.Outcome Decide(
        long elapsedMs = 0,
        long silenceMs = 0,
        long realOutputSilenceMs = 0,
        long subtreeIdleForMs = 0,
        bool firstPulseReceived = true,
        int firstOutputTimeoutMs = 3_600_000,
        int inactivityTimeoutMs = 3_600_000,
        int absoluteCeilingMs = 0,
        ActivityWatchdog.WedgeSample sample = default) =>
        ActivityWatchdog.DecideOutcome(
            elapsedMs, silenceMs, realOutputSilenceMs, subtreeIdleForMs,
            firstPulseReceived, firstOutputTimeoutMs, inactivityTimeoutMs,
            absoluteCeilingMs, sample);

    /// <summary>
    /// Per-tier first-output window (frontier vs cheap), sleep-free. Before the first
    /// pulse the decision compares elapsed-from-start to the tier's first-output
    /// window: a 3 s slow start FiresStall at cheap's 2 s window but is Disarmed at
    /// frontier's 30 s window — so a frontier stage is not killed at the cheap
    /// threshold. (The runner picking frontier's window, not cheap's, is pinned by
    /// ResolveTierWindows below.)
    /// </summary>
    [Fact]
    public void DecideOutcome_BeforeFirstOutput_FrontierWindowSurvivesSlowStartThatKillsCheap()
    {
        Assert.Equal(
            ActivityWatchdog.Outcome.FiredStall,
            Decide(elapsedMs: 3_000, firstPulseReceived: false, firstOutputTimeoutMs: 2_000));

        Assert.Equal(
            ActivityWatchdog.Outcome.Disarmed,
            Decide(elapsedMs: 3_000, firstPulseReceived: false, firstOutputTimeoutMs: 30_000));
    }

    [Fact]
    public void DecideOutcome_AfterFirstOutput_LongSilenceUnderInactivityWindow_Disarmed()
    {
        Assert.Equal(
            ActivityWatchdog.Outcome.Disarmed,
            Decide(elapsedMs: 15_000, silenceMs: 15_000, firstPulseReceived: true,
                firstOutputTimeoutMs: 10_000, inactivityTimeoutMs: 600_000));
    }

    /// <summary>
    /// Regression (1): stdout bytes are liveness pulses, so a process that writes
    /// stdout but NO trace file must NOT be killed by the first-output watchdog (the
    /// original false-kill scenario). A stdout pulse sets firstPulseReceived,
    /// flipping the watchdog into the inactivity phase — so even 2.5 s elapsed (past
    /// the 2 s first-output window) with only 0.5 s of inter-pulse silence (≪ the
    /// inactivity window) stays Disarmed, exactly as a trace pulse would.
    /// </summary>
    [Fact]
    public void DecideOutcome_StdoutPulseDisarmsFirstOutput_SurvivesPastFirstOutputWindow()
    {
        Assert.Equal(
            ActivityWatchdog.Outcome.Disarmed,
            Decide(elapsedMs: 2_500, silenceMs: 500, firstPulseReceived: true,
                firstOutputTimeoutMs: 2_000, inactivityTimeoutMs: 600_000));
    }

    /// <summary>
    /// Regression (3): A process that pulses once, then goes silent
    /// past the inactivity window. Decision-seam test.
    /// </summary>
    [Fact]
    public void DecideOutcome_FirstPulseThenSilence_FiresAtInactivityDeadline()
    {
        // One pulse at 0 ms → firstPulseReceived=true.  Then 4 s of total
        // silence with a 3 s inactivity window → FiredStall.
        Assert.Equal(
            ActivityWatchdog.Outcome.FiredStall,
            Decide(elapsedMs: 4_000, silenceMs: 4_000, firstPulseReceived: true,
                firstOutputTimeoutMs: 90_000, inactivityTimeoutMs: 3_000));
    }

    /// <summary>
    /// Absolute ceiling fires even when the agent is pulsing frequently
    /// (low silenceMs keeps the inactivity watchdog disarmed).  The ceiling
    /// is a hard wall-clock backstop, not a progress heuristic.
    /// </summary>
    [Fact]
    public void DecideOutcome_FiresAbsoluteCeiling_WhenElapsedExceedsCeiling()
    {
        // Elapsed meets the 5 s ceiling; silence is only 500 ms (active pulses).
        Assert.Equal(
            ActivityWatchdog.Outcome.FiredAbsoluteCeiling,
            Decide(elapsedMs: 5_000, silenceMs: 500, firstPulseReceived: true,
                inactivityTimeoutMs: 600_000, absoluteCeilingMs: 5_000));
    }

    /// <summary>
    /// When both the absolute ceiling AND a stall condition (silence ≥ inactivity
    /// window) are met simultaneously, the ceiling takes priority — the outcome
    /// must be FiredAbsoluteCeiling, not FiredStall.
    /// </summary>
    [Fact]
    public void DecideOutcome_CeilingWinsOverStall()
    {
        // Both ceiling (elapsed ≥ 5s) and stall (silence ≥ 3s inactivity window)
        // are met.  Ceiling must win.
        Assert.Equal(
            ActivityWatchdog.Outcome.FiredAbsoluteCeiling,
            Decide(elapsedMs: 5_000, silenceMs: 5_000, firstPulseReceived: true,
                inactivityTimeoutMs: 3_000, absoluteCeilingMs: 5_000));
    }

    /// <summary>
    /// Under the absolute ceiling, the ceiling does NOT fire — only the
    /// inactivity/stall path can fire.  This validates no false-positive from
    /// the ceiling on a slow-but-legitimate stage (e.g. a long tool call).
    /// </summary>
    [Fact]
    public void DecideOutcome_DoesNotFireCeiling_WhenUnderCeiling()
    {
        // Elapsed 4 s is under the 10 s ceiling; silence 5 s exceeds the 3 s
        // inactivity window → FiredStall, NOT the ceiling.
        Assert.Equal(
            ActivityWatchdog.Outcome.FiredStall,
            Decide(elapsedMs: 4_000, silenceMs: 5_000, firstPulseReceived: true,
                inactivityTimeoutMs: 3_000, absoluteCeilingMs: 10_000));
    }

    /// <summary>
    /// When absoluteCeilingMs is 0 (disabled), the ceiling path is inert even
    /// at extreme elapsed durations — only the stall path can fire.  This
    /// documents the pre-fix behavior: a flailing-but-active agent would run
    /// unbounded.
    /// </summary>
    [Fact]
    public void DecideOutcome_CeilingDisabled_DoesNotFire()
    {
        // Ceiling is 0 (disabled).  Elapsed 100 s is huge, but the ceiling
        // short-circuit (absoluteCeilingMs > 0) is false, so only stall fires.
        Assert.Equal(
            ActivityWatchdog.Outcome.FiredStall,
            Decide(elapsedMs: 100_000, silenceMs: 10_000, firstPulseReceived: true,
                inactivityTimeoutMs: 5_000, absoluteCeilingMs: 0));
    }

    /// <summary>
    /// Regression (4): periodic stdout + trace pulses keep silence well under the
    /// inactivity window, so a stage survives FAR past what would have been the old
    /// flat cap (10 s). With pulses every ~2 s (silence ≤ 2 s) against a 5 s
    /// inactivity window and no absolute ceiling, the decision is Disarmed at every
    /// elapsed point — including 16 s in, well past the old cap.
    /// </summary>
    [Fact]
    public void DecideOutcome_PulsesResetSilence_DisarmedFarPastOldFlatCap()
    {
        for (var elapsedMs = 2_000L; elapsedMs <= 16_000L; elapsedMs += 2_000L)
        {
            Assert.Equal(
                ActivityWatchdog.Outcome.Disarmed,
                Decide(elapsedMs: elapsedMs, silenceMs: 2_000, firstPulseReceived: true,
                    inactivityTimeoutMs: 5_000, absoluteCeilingMs: 0));
        }
    }

    /// <summary>
    /// Regression (5): when an absolute ceiling is set it kills the stage despite
    /// continuous activity. Even with tiny silence (1 s pulses), once elapsed reaches
    /// the 10 s ceiling the decision is FiredAbsoluteCeiling — and just before it,
    /// Disarmed.
    /// </summary>
    [Fact]
    public void DecideOutcome_AbsoluteCeilingReached_FiresDespiteContinuousActivity()
    {
        Assert.Equal(
            ActivityWatchdog.Outcome.Disarmed,
            Decide(elapsedMs: 9_000, silenceMs: 500, firstPulseReceived: true,
                inactivityTimeoutMs: 600_000, absoluteCeilingMs: 10_000));

        Assert.Equal(
            ActivityWatchdog.Outcome.FiredAbsoluteCeiling,
            Decide(elapsedMs: 10_000, silenceMs: 500, firstPulseReceived: true,
                inactivityTimeoutMs: 600_000, absoluteCeilingMs: 10_000));
    }

    /// <summary>
    /// Regression (6): per-tier inactivity windows are honored. The SAME 8 s of
    /// silence kills the cheap tier (3 s window → FiredStall) but is survived by the
    /// frontier tier (30 s window → Disarmed).
    /// </summary>
    [Fact]
    public void DecideOutcome_PerTierInactivityWindows_CheapKilledFrontierSurvivesSameSilence()
    {
        Assert.Equal(
            ActivityWatchdog.Outcome.FiredStall,
            Decide(silenceMs: 8_000, firstPulseReceived: true, inactivityTimeoutMs: 3_000));

        Assert.Equal(
            ActivityWatchdog.Outcome.Disarmed,
            Decide(silenceMs: 8_000, firstPulseReceived: true, inactivityTimeoutMs: 30_000));
    }

    /// <summary>
    /// Runner→watchdog WIRING: <see cref="SwivalSubagentRunner.ResolveTierWindows"/>
    /// maps each configured tier to ITS first-output/inactivity window and falls back
    /// to the flat defaults for an unmapped tier. This pins the coverage the former
    /// per-tier integration tests provided (that "frontier" resolves to its larger
    /// window, not "cheap"'s) without a real clock.
    /// </summary>
    [Fact]
    public void ResolveTierWindows_MapsEachConfiguredTier_ElseFlatFallback()
    {
        var config = TestConfig() with
        {
            FirstOutputTimeoutMsByTier = new Dictionary<string, int>
            {
                ["cheap"] = 2_000,
                ["balanced"] = 120_000,
                ["frontier"] = 30_000
            },
            FirstOutputTimeoutMs = 99_000,
            InactivityTimeoutMsByTier = new Dictionary<string, int>
            {
                ["cheap"] = 3_000,
                ["balanced"] = 600_000,
                ["frontier"] = 45_000
            },
            InactivityTimeoutMs = 88_000
        };

        Assert.Equal((2_000, 3_000), SwivalSubagentRunner.ResolveTierWindows(config, "cheap"));
        Assert.Equal((120_000, 600_000), SwivalSubagentRunner.ResolveTierWindows(config, "balanced"));
        Assert.Equal((30_000, 45_000), SwivalSubagentRunner.ResolveTierWindows(config, "frontier"));
        // Unmapped tier → the flat fallbacks.
        Assert.Equal((99_000, 88_000), SwivalSubagentRunner.ResolveTierWindows(config, "unknown"));
    }

    /// <summary>
    /// WIRING edge: a null per-tier inactivity map falls back to the flat
    /// <see cref="RelayConfig.InactivityTimeoutMs"/> for every tier (the default
    /// config shape), while the first-output map still resolves.
    /// </summary>
    [Fact]
    public void ResolveTierWindows_NullInactivityMap_FallsBackToFlatInactivity()
    {
        var config = TestConfig() with
        {
            FirstOutputTimeoutMsByTier = new Dictionary<string, int> { ["cheap"] = 2_000 },
            InactivityTimeoutMsByTier = null,
            InactivityTimeoutMs = 600_000
        };

        Assert.Equal((2_000, 600_000), SwivalSubagentRunner.ResolveTierWindows(config, "cheap"));
    }

    // ── (A) Pure decision gate — the exact production algorithm ────────────────

    /// <summary>
    /// FOUR gates must hold to declare a wedge: real-output silence ≥ the inactivity
    /// window, the agent subtree SUSTAINED-idle for ≥ the inactivity window (a single
    /// idle sample window is NOT enough — a bursty/working agent shows transient idle
    /// windows between model turns), an ESTABLISHED backend socket, and first output
    /// seen. Anything less (recent output, recently-busy subtree, no socket, or before
    /// first output) must NOT fire — proving the detector is strictly additive and the
    /// cpu-pulse liveness signal is honored on this path too.
    /// </summary>
    [Theory]
    // firstPulse, silenceMs, inactivityMs, subtreeIdleForMs, subtreeIdle, socket, expectWedge
    [InlineData(true, 6_000, 6_000, 6_000, true, true, true)]    // exact wedge — fires
    [InlineData(true, 9_999, 6_000, 9_999, true, true, true)]    // well past window — fires
    [InlineData(true, 5_999, 6_000, 5_999, true, true, false)]   // silence just under window
    [InlineData(true, 60_000, 6_000, 60_000, false, true, false)] // subtree BUSY now — no kill
    [InlineData(true, 60_000, 6_000, 60_000, true, false, false)] // no backend socket — no kill
    [InlineData(false, 60_000, 6_000, 60_000, true, true, false)] // before first output — no kill
    // INCIDENT shape: real-output silent + latest sample idle + socket up, BUT a CPU
    // burst happened within the window (sustained-idle < window) — healthy, no kill.
    [InlineData(true, 60_000, 6_000, 2_000, true, true, false)]
    [InlineData(true, 60_000, 6_000, 5_999, true, true, false)]  // sustained-idle just under window
    public void TryDecideSocketWedge_FiresOnlyWhenAllGatesHold(
        bool firstPulse, long silenceMs, int inactivityMs, long subtreeIdleForMs,
        bool subtreeIdle, bool socket, bool expectWedge)
    {
        var decided = ActivityWatchdog.TryDecideSocketWedge(
            firstPulse, silenceMs, subtreeIdleForMs, inactivityMs,
            new ActivityWatchdog.WedgeSample(subtreeIdle, socket));

        Assert.Equal(expectWedge, decided);
    }

    private static RelayConfig TestConfig() =>
        new(
            "llm-tasks",
            "true",
            "true",
            [],
            new Dictionary<string, string> { ["cheap"] = "cheap" },
            true,
            1,
            1,
            false,
            true,
            5_000,
            300_000,
            new Dictionary<string, int> { ["cheap"] = 90_000, ["balanced"] = 120_000, ["frontier"] = 660_000 },
            660_000,
            2,
            InactivityTimeoutMsByTier: null,
            InactivityTimeoutMs: 600_000);
}

using VisualRelay.Core.Execution;

namespace VisualRelay.Tests;

/// <summary>
/// Virtualized <see cref="ActivityWatchdog.WaitAsync"/> loop tests.
/// A <see cref="ManualTimeProvider"/> drives the watchdog polling loop and
/// background-pump <c>Task.Delay</c> calls instantly — no real waiting,
/// no wall-clock sensitivity. These tests do NOT need serialization and
/// run in parallel with all other non-Watchdog tests.
/// </summary>
public sealed partial class ActivityWatchdogDecisionTests
{
    // A background "cpu" pulse pump: keeps resetting the ordinary inactivity
    // deadline (exactly what masked the wedge in production) until cancelled. The
    // token is a parameter (not a captured `using` local) so the pump owns no
    // disposable it could outlive.
    private static Task StartCpuPulsePump(
        ActivityWatchdog watchdog, CancellationToken stop, TimeProvider? timeProvider = null) =>
        Task.Run(async () =>
        {
            var tp = timeProvider ?? TimeProvider.System;
            while (!stop.IsCancellationRequested)
            {
                watchdog.Pulse("cpu");
                try { await Task.Delay(TimeSpan.FromMilliseconds(50), tp, stop); }
                catch (OperationCanceledException) { return; }
            }
        }, stop);

    // Wedge-sample pump emulating a BURSTY working agent: a CPU burst (busy sample)
    // then several idle samples, repeating — so sustained-idle never reaches a full
    // window. The token is a PARAMETER (not a captured `using` local) so the pump
    // owns no disposable it could outlive (mirrors StartCpuPulsePump).
    private static Task StartBurstyWedgePump(
        ActivityWatchdog watchdog, int windowMs, CancellationToken stop, TimeProvider? timeProvider = null) =>
        Task.Run(async () =>
        {
            var tp = timeProvider ?? TimeProvider.System;
            while (!stop.IsCancellationRequested)
            {
                watchdog.RecordWedgeSample(new ActivityWatchdog.WedgeSample(
                    SubtreeIdle: false, BackendSocketEstablished: true)); // CPU burst
                for (var i = 0; i < 3 && !stop.IsCancellationRequested; i++)
                {
                    watchdog.RecordWedgeSample(new ActivityWatchdog.WedgeSample(
                        SubtreeIdle: true, BackendSocketEstablished: true)); // idle between bursts
                    try { await Task.Delay(TimeSpan.FromMilliseconds(windowMs / 8), tp, stop); }
                    catch (OperationCanceledException) { return; }
                }
            }
        }, stop);

    // Wedge-sample pump emulating a SUSTAINED-idle wedge: only idle samples (socket
    // up), refreshed so the verdict never goes stale. Token is a parameter, as above.
    private static Task StartIdleWedgePump(
        ActivityWatchdog watchdog, CancellationToken stop, TimeProvider? timeProvider = null) =>
        Task.Run(async () =>
        {
            var tp = timeProvider ?? TimeProvider.System;
            while (!stop.IsCancellationRequested)
            {
                watchdog.RecordWedgeSample(new ActivityWatchdog.WedgeSample(
                    SubtreeIdle: true, BackendSocketEstablished: true));
                try { await Task.Delay(TimeSpan.FromMilliseconds(50), tp, stop); }
                catch (OperationCanceledException) { return; }
            }
        }, stop);

    // ── (B) Watchdog loop — cpu pulses mask the deadline, wedge still fires ─────

    /// <summary>
    /// The incident shape: a real-output burst, then the "cpu" pulse keeps firing
    /// (masking the inactivity deadline) while the wedge sample reports an idle
    /// subtree + an ESTABLISHED backend socket. The watchdog must still fire — via
    /// the socket-wedge path, not the ordinary inactivity path.
    /// Virtualized: a ManualTimeProvider drives the watchdog loop and pump delays
    /// instantly — no real waiting, no wall-clock sensitivity.
    /// </summary>
    [Fact]
    public async Task WaitAsync_CpuPulseMasksDeadline_SocketWedgeStillFires()
    {
        const int inactivityMs = 1_500;
        var time = new ManualTimeProvider();
        using var kill = new CancellationTokenSource();
        var watchdog = new ActivityWatchdog(
            firstOutputTimeoutMs: 1_000, inactivityTimeoutMs: inactivityMs,
            absoluteCeilingMs: 0, kill, timeProvider: time);

        // Early real output, then idle + socket established.
        watchdog.Pulse("trace");
        watchdog.RecordWedgeSample(new ActivityWatchdog.WedgeSample(SubtreeIdle: true, BackendSocketEstablished: true));

        using var pumpCts = new CancellationTokenSource();
        var pump = StartCpuPulsePump(watchdog, pumpCts.Token, time);

        var watchdogTask = watchdog.WaitAsync(CancellationToken.None);
        for (var i = 0; i < 200 && !watchdogTask.IsCompleted; i++)
        {
            time.Advance(TimeSpan.FromMilliseconds(50));
            await Task.Delay(1);
        }
        var result = await watchdogTask;
        await pumpCts.CancelAsync();
        await pump;

        Assert.Equal(ActivityWatchdog.Outcome.FiredSocketWedge, result.Outcome);
        Assert.True(kill.IsCancellationRequested);
        Assert.True(result.SilenceMs >= inactivityMs,
            $"wedge SilenceMs should report real-output silence ≥ {inactivityMs}ms, got {result.SilenceMs}ms");
        Assert.True(result.SubtreeIdleForMs >= inactivityMs,
            $"wedge should report sustained-idle ≥ {inactivityMs}ms, got {result.SubtreeIdleForMs}ms");
    }

    /// <summary>
    /// Conservative guard: a genuinely-working agent whose target filesystem froze
    /// its trace view (the 2026-06-10 false-kill class) keeps a BUSY subtree even
    /// though real output is silent and a backend socket is open. The cpu pulse
    /// keeps the deadline alive AND the wedge sample reports a busy subtree, so the
    /// watchdog must NOT fire. We assert it stays disarmed for several windows.
    /// Virtualized: ManualTimeProvider advances well past several inactivity windows
    /// instantly — the cpu pump and watchdog both see the same virtual clock.
    /// </summary>
    [Fact]
    public async Task WaitAsync_BusySubtree_NotKilled_EvenWithSocketAndSilence()
    {
        const int inactivityMs = 800;
        var time = new ManualTimeProvider();
        using var kill = new CancellationTokenSource();
        var watchdog = new ActivityWatchdog(
            firstOutputTimeoutMs: 1_000, inactivityTimeoutMs: inactivityMs,
            absoluteCeilingMs: 0, kill, timeProvider: time);

        watchdog.Pulse("trace");
        watchdog.RecordWedgeSample(new ActivityWatchdog.WedgeSample(SubtreeIdle: false, BackendSocketEstablished: true));

        using var pumpCts = new CancellationTokenSource();
        var pump = StartCpuPulsePump(watchdog, pumpCts.Token, time);

        using var stopCts = new CancellationTokenSource();
        var watchdogTask = watchdog.WaitAsync(stopCts.Token);
        for (var i = 0; i < 120 && !watchdogTask.IsCompleted; i++)
        {
            time.Advance(TimeSpan.FromMilliseconds(50));
            await Task.Delay(1);
        }
        await pumpCts.CancelAsync();
        await pump;
        await stopCts.CancelAsync();
        time.Advance(TimeSpan.FromMilliseconds(200));
        var result = await watchdogTask;

        Assert.Equal(ActivityWatchdog.Outcome.Disarmed, result.Outcome);
        Assert.False(kill.IsCancellationRequested);
    }

    /// <summary>
    /// THE 2026-06-21 INCIDENT (must NOT fire): a healthy, actively-working agent on
    /// a frozen-trace filesystem. Real output is silent past the inactivity window and
    /// a backend socket is ESTABLISHED, but the agent has bursty CPU — between model
    /// turns the latest sample reads idle, yet it had a busy burst WITHIN the window.
    /// The single-sample gate false-killed this; the sustained-idle gate must not. A
    /// cpu pump masks the ordinary deadline the whole time — the watchdog must stay
    /// disarmed across several windows.
    /// Virtualized: ManualTimeProvider drives the watchdog loop and both pumps
    /// instantly — no real waiting.
    /// </summary>
    [Fact]
    public async Task WaitAsync_BurstyAgent_IdleSampleButRecentCpuBurst_NotKilled()
    {
        const int inactivityMs = 1_000;
        var time = new ManualTimeProvider();
        using var kill = new CancellationTokenSource();
        var watchdog = new ActivityWatchdog(
            firstOutputTimeoutMs: 1_000, inactivityTimeoutMs: inactivityMs,
            absoluteCeilingMs: 0, kill, timeProvider: time);

        watchdog.Pulse("trace"); // early real output, then trace freezes

        using var pumpCts = new CancellationTokenSource();
        var cpuPump = StartCpuPulsePump(watchdog, pumpCts.Token, time);
        var samplePump = StartBurstyWedgePump(watchdog, inactivityMs, pumpCts.Token, time);

        using var stopCts = new CancellationTokenSource();
        var watchdogTask = watchdog.WaitAsync(stopCts.Token);
        for (var i = 0; i < 240 && !watchdogTask.IsCompleted; i++)
        {
            time.Advance(TimeSpan.FromMilliseconds(50));
            await Task.Delay(1);
        }
        await pumpCts.CancelAsync();
        await cpuPump;
        await samplePump;
        await stopCts.CancelAsync();
        time.Advance(TimeSpan.FromMilliseconds(200));
        var result = await watchdogTask;

        Assert.Equal(ActivityWatchdog.Outcome.Disarmed, result.Outcome);
        Assert.False(kill.IsCancellationRequested);
    }

    /// <summary>
    /// TRUE WEDGE through the loop (must STILL fire): a recv()-blocked dead-socket
    /// agent stays idle the ENTIRE window — every wedge sample reports idle — with a
    /// backend socket ESTABLISHED and real output silent. The cpu pump masks the
    /// ordinary deadline (exactly what hid the production wedge). The sustained-idle
    /// gate must still fire the socket-wedge kill. Preserves the 3ab3ce6 behavior.
    /// Virtualized: ManualTimeProvider drives the loop and both pumps instantly.
    /// </summary>
    [Fact]
    public async Task WaitAsync_SustainedIdlePlusSocket_StillFiresSocketWedge()
    {
        const int inactivityMs = 1_200;
        var time = new ManualTimeProvider();
        using var kill = new CancellationTokenSource();
        var watchdog = new ActivityWatchdog(
            firstOutputTimeoutMs: 1_000, inactivityTimeoutMs: inactivityMs,
            absoluteCeilingMs: 0, kill, timeProvider: time);

        watchdog.Pulse("trace");

        using var pumpCts = new CancellationTokenSource();
        var cpuPump = StartCpuPulsePump(watchdog, pumpCts.Token, time);
        var samplePump = StartIdleWedgePump(watchdog, pumpCts.Token, time);

        var watchdogTask = watchdog.WaitAsync(CancellationToken.None);
        for (var i = 0; i < 200 && !watchdogTask.IsCompleted; i++)
        {
            time.Advance(TimeSpan.FromMilliseconds(50));
            await Task.Delay(1);
        }
        var result = await watchdogTask;

        await pumpCts.CancelAsync();
        await cpuPump;
        await samplePump;

        Assert.Equal(ActivityWatchdog.Outcome.FiredSocketWedge, result.Outcome);
        Assert.True(kill.IsCancellationRequested);
        Assert.True(result.SilenceMs >= inactivityMs,
            $"wedge SilenceMs should be ≥ {inactivityMs}ms, got {result.SilenceMs}ms");
    }

    /// <summary>
    /// Unit test: drive <see cref="ActivityWatchdog"/> with a simulated
    /// pulse history matching the 2026-06-12 socket-wedge incident —
    /// pulses for the first ~2 min (simulated), then total silence for
    /// the full inactivity window.  The watchdog must fire at the
    /// inactivity deadline ± one polling interval (~200 ms).
    ///
    /// This test isolates the watchdog's deadline logic from all upstream
    /// pulse sources.  If it passes while the integration tests fail, the
    /// bug is upstream of the watchdog (in a <c>Pulse(...)</c> call site).
    /// Virtualized: ManualTimeProvider drives the loop and the 50ms inter-pulse
    /// gap instantly — no real waiting, no wall-clock sensitivity.
    /// </summary>
    [Fact]
    public async Task WaitAsync_BurstThenTotalSilence_FiresAtInactivityDeadline()
    {
        const int inactivityTimeoutMs = 2_000;
        var time = new ManualTimeProvider();
        using var kill = new CancellationTokenSource();
        var watchdog = new ActivityWatchdog(
            firstOutputTimeoutMs: 1_000,
            inactivityTimeoutMs: inactivityTimeoutMs,
            absoluteCeilingMs: 0,
            kill, timeProvider: time);

        // Simulate early output burst (representing the first ~2 min of real
        // activity: stdout lines, trace-file creation).
        watchdog.Pulse("stdout");
        // Model a real ~50ms gap between pulses via virtual time advance.
        time.Advance(TimeSpan.FromMilliseconds(50));
        watchdog.Pulse("trace");

        // Now total silence — no more pulses of any kind.
        // Advance virtual time in small steps with short real delays so the
        // watchdog loop detects inactivity and fires the stall.
        var watchdogTask = watchdog.WaitAsync(CancellationToken.None);
        for (var i = 0; i < 120 && !watchdogTask.IsCompleted; i++)
        {
            time.Advance(TimeSpan.FromMilliseconds(50));
            await Task.Delay(1);
        }
        var result = await watchdogTask;

        Assert.Equal(ActivityWatchdog.Outcome.FiredStall, result.Outcome);
        // Last real pulse before silence was "trace".
        Assert.Equal("trace", result.LastPulseSource);
        Assert.True(result.SilenceMs >= inactivityTimeoutMs,
            $"Expected silence >= {inactivityTimeoutMs}ms, got {result.SilenceMs}ms");
        Assert.True(kill.IsCancellationRequested);
    }
}

